model = pulp.LpProblem("Ambulance_and_Station_Placement")


# Constraints
for j in range(1, N + 1):
    if dj.get(j, 0) != 1:  
        for i in SF_j[j]:  
            model += XB_ij[i, j] <= 0

for i in range(1, N+1):
    model += pulp.lpSum(XA_ij[i, j] for j in [k for k, v in SF_j.items() if i in list(v)]) + pulp.lpSum(XB_ij[i, j] for j in [k for k, v in SF_j.items() if i in list(v)]) == 1          

for j in range(1,N+1):
 model += XA_ij[j, j] + XB_ij[j, j] <= 1   

for i in range(1,N+1):
  if dS_i[i] == 1:
    model += pulp.lpSum(XS_ij[i, j] for j in [k for k, v in SS_j.items() if i in list(v)] if j != i) == 1

for j in range(1, N + 1):
    for i in range(1, N + 1):  
        if i != j:
          model += XA_ij[i, j] <= XA_ij[j, j]
          model += XB_ij[i, j] <= XB_ij[j, j]
          
for j in range(1,N+1):
      for i in SS_j[j]:
       if i != j:
        model += XS_ij[i, j] <= XA_ij[j, j] + XB_ij[j, j] 
        

for j in range(1, N + 1):
    
    total_power_allocated_to_j = pulp.lpSum((XA_ij[i, j] + XB_ij[i, j]) * Pi[i] for i in range(1, N + 1))
       
    model += total_power_allocated_to_j <= Pmax * (nA_j[j] + nB_j[j]), f"MaxPowerConstraint_{j}"
    model += total_power_allocated_to_j >= Pmin * (nA_j[j] + nB_j[j]), f"MinPowerConstraint_{j}"

        
        
for j in range(1,N+1):
   model += XA_ij[j, j] <= nA_j[j]
   model += nA_j[j] <= M * XA_ij[j, j]
   model += XB_ij[j, j] == nB_j[j] 
   
